(()=>{const OLD_FOLDER="https://drive.google.com/drive/folders/1UTIQESYvJcNdKXNsDdDs0dRCrDzs5JvF";const NEW_FOLDER="https://drive.google.com/drive/folders/1iwuKlMfb8JSLV86ZlbPNQg1ri2Q0CeNl";const API="https://rcmusic-eventos.onrender.com/api";const patchLabel=()=>document.querySelectorAll("button").forEach(button=>{const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT);const nodes=[];let node;while(node=walker.nextNode())nodes.push(node);nodes.forEach(text=>{if(text.nodeValue.includes("Backup actualizado en Drive"))text.nodeValue=text.nodeValue.replace("Backup actualizado en Drive","Actualización y Utilidades Dj.")})});const originalOpen=window.open;window.open=(url,...args)=>originalOpen.call(window,url===OLD_FOLDER?NEW_FOLDER:url,...args);const driveHeaders=()=>{const session=localStorage.getItem("rc_drive_session")||sessionStorage.getItem("rc_drive_session")||"";return {"Content-Type":"application/json",...(session?{"X-Drive-Session":session}:{})}};const grantReadOnly=async email=>{if(!email)return;try{await fetch(`${API}/drive/grant-folder-access`,{method:"POST",headers:driveHeaders(),credentials:"include",body:JSON.stringify({email})})}catch{}};const emailFromButton=button=>{let el=button;for(let i=0;i<6&&el;i++,el=el.parentElement){const match=el.innerText?.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(match)return match[0].toLowerCase()}return ""};document.addEventListener("click",event=>{const button=event.target.closest("button");if(!button)return;const label=button.textContent.trim();if(/^(Aprobar|Aceptar|Approve|Accept)/i.test(label)){const email=emailFromButton(button);if(email)setTimeout(()=>grantReadOnly(email),1800)}},true);patchLabel();new MutationObserver(patchLabel).observe(document.documentElement,{childList:true,subtree:true});})();
